import json

print(json.loads('{"a": 2, "b": 1, "a": 3}') == json.loads('{"b": 1, "a": 3}'))
print(json.loads('{"a": {"b": 1}}') != json.loads('{"a": {"b": 2}}'))
print(json.loads('[1, true, 0]') == json.loads('[1.0, 1, -0.0]'))
print(json.loads('[1, 2]') == json.loads('[2, 1]'))
print(json.loads('9007199254740993') == json.loads('9007199254740992.0'))
print(json.loads('"a"') == json.loads('"a"'))
print(json.loads('null') == json.loads('false'))
nan = json.loads('NaN')
print(nan == nan)
print(nan == json.loads('NaN'))
print(json.loads('[NaN]') == json.loads('[NaN]'))
print(json.loads('{"x": NaN}') == json.loads('{"x": NaN}'))
a = json.loads('[1]')
b = json.loads('[1, 2]')
print(a == b)
a.append(b[1])
print(a == b)
nan_source = json.loads("[NaN]")
nan = nan_source[0]
left = json.loads("[]")
right = json.loads("[]")
left.append(nan)
right.append(nan)
print(left == left)
print(left == right)
other = json.loads("[]")
other_nan_source = json.loads("[NaN]")
other.append(other_nan_source[0])
print(left == other)
prefix = '{"x": [' + '0,' * 2200
large = json.loads(prefix + 'NaN]}')
print(large == json.loads(prefix + 'NaN]}'))
print(large != json.loads(prefix + '1]}'))
